\label{gt}
Let $k \geq 2$.
The set of primes $\mathbf P$ contains arithmetic progressions of arbitrary length. Moreover, given any subset $S \subseteq \mathbf P_n$ of size $|S|=\Omega (|\mathbf P_n|) $, the number of $k$-APs in $S$ is 
$\Theta (n^2/\log ^k n)$.\footnote{Note that the moreover part of Theorem~\ref{gt} is implicit in~\cite{greentao}. An explicit proof of (a strengthening of) this part of Theorem~\ref{gt} can be found in, e.g.,~\cite[Theorem~1.2]{cmt}.}

\label{gt1}
Let $k \geq 3$. 
$$\lim _{n \rightarrow \infty} \mathbb P [\, \mathbf P_{n,p} \text{ contains a } k\text{-AP}]=\begin{cases}
0 &\text{ if } p=o(n^{-2/k}\log n); \\
 1 &\text{ if } p=\omega ( n^{-2/k}\log n). \end{cases} $$

$$\lim _{n \rightarrow \infty} \mathbb P [\, \mathbf P_{n,p} \text{ contains a } k\text{-AP}]=\begin{cases}
0 &\text{ if } p=o(n^{-2/k}\log n); \\
 1 &\text{ if } p=\omega ( n^{-2/k}\log n). \end{cases} $$

\label{rvdwp}
Let $k \geq 3$ and $r \geq 2$.
There are constants $c,C>0$ such that
$$\lim _{n \rightarrow \infty} \mathbb P [ \, \mathbf P_{n,p} \text{ is } (r,k)\text{-van der Waerden}]=\begin{cases}
0 &\text{ if } p \leq cn^{-\frac{1}{k-1}}\log n; \\
 1 &\text{ if } p \geq Cn^{-\frac{1}{k-1}}\log n.\end{cases}$$

$$\lim _{n \rightarrow \infty} \mathbb P [ \, \mathbf P_{n,p} \text{ is } (r,k)\text{-van der Waerden}]=\begin{cases}
0 &\text{ if } p \leq cn^{-\frac{1}{k-1}}\log n; \\
 1 &\text{ if } p \geq Cn^{-\frac{1}{k-1}}\log n.\end{cases}$$

\label{thm:bdh} 
Let $\mathbb F$ be a finite field and $A$ be an $\ell \times k$ matrix with entries from $\mathbb F$. The following statements are equivalent:
\begin{itemize}
\item for all $r \in \mathbb{N}$, there exists $n_0=n_0(r, |\mathbb F|, k)\in\mathbb N$ such that for all $n \geq n_0$ every $r$-colouring of $\mathbb F^n\setminus\{0\}$ yields a monochromatic solution to $Ax = 0$ in $\mathbb F^n\setminus\{0\}$;
\item the matrix $A$ is partition regular in $\mathbb{F}^{\mathbb{N}}\setminus \{0\}$;
\item the matrix $A$ satisfies the columns condition over $\mathbb F$.
\end{itemize}

\label{fact}
For an integer matrix $A$, the following statements are equivalent:
\begin{enumerate}[label=(\Alph*)]
    \item $A$ is partition regular;\label{item:case1}
    \item for every $r\in\mathbb N$, there exists $n_0\in\mathbb N$ such that for all $n\ge n_0$ every $r$-colouring of $[n]:=\{1,2,\dots,n\}$ yields a monochromatic solution to $Ax=0$ in $[n]$. \qed \label{item:case2}
\end{enumerate}

\label{thm:supersatprimes}
Given any $r, k\in \mathbb N$ with $k \geq 3$,
any $r$-colouring of $\mathbf P_n$ yields $\Theta(n^2/\log^k n)$ monochromatic $k$-APs in $\mathbf P_n$. \qed

\label{thm:fieldsupersat}
Let $r \in \mathbb{N}$, let $\mathbb F$ be a finite field and let $A$ be an $\ell \times k$ matrix with entries in $\mathbb F$ and rank $\ell$ which satisfies the columns condition over $\mathbb F$.
There exist $\delta,n_0>0$ such that, for all $n \geq n_0$, every $r$-colouring of  $\mathbb F^n\setminus\{0\}$ yields at least $\delta|\mathbb F|^{n(k-\ell)}$ monochromatic solutions to $Ax=0$ in $\mathbb F^n\setminus\{0\}$.

\label{thm:supersat-d}
Let $r,d\in\mathbb N$ and let $A$ be a partition regular $\ell \times k$ integer matrix of rank $\ell$.
There exist $\delta,n_0>0$ such that the following holds: for all $n \ge n_0$, every $r$-colouring of $[n]^d$ yields at least $\delta n^{d(k-\ell)}$ monochromatic solutions to $Ax=0$ in $[n]^d$.

