\label{def:compatibility}
Let $(S_n)_{n\in\mathbb N}$ be a sequence of finite subsets of abelian groups and $A$ be an $\ell\times k$ integer matrix with $k\ge3$. We say $(S_n)_{n\in\mathbb N}$ is \emph{compatible} with respect to $A$ if there exists a sequence $(X_n)_{n\in\mathbb N}$ of subsets $X_n\subseteq[k]$ with $|X_n|\ge3$ for all $n\in\mathbb N$ such that the following holds. We have $p_{X_n}(A,S_n)= \Omega(\hat p(A,S_n))$ and, for all sequences $(W_n)_{n\in\mathbb N}$ and $(W'_n)_{n\in\mathbb N}$ with $W_n,W'_n\subset  X_n$, $|W_n|=2$ and $|W'_n|\ge2$,
\begin{align}\label{eq:compatible}
\frac{|S_n|^2}{|\mathrm{Sol}_{S_n}^A(W_n)|}\left(\frac{p_{W'_n}(A,S_n)}{p_{X_n}(A,S_n)}\right)^{|W'_n|-1}\to0
\end{align}
as $n\to\infty$.

\begin{align}\label{eq:compatible}
\frac{|S_n|^2}{|\mathrm{Sol}_{S_n}^A(W_n)|}\left(\frac{p_{W'_n}(A,S_n)}{p_{X_n}(A,S_n)}\right)^{|W'_n|-1}\to0
\end{align}

\label{lem:randomRado}
Let $r\geq 2$, $k  \geq 3$ and $\ell\geq 1$ be integers. Let $(S_n)_{n \in \mathbb N}$ be a sequence of finite subsets of abelian groups, $A$ be an $\ell \times k$ integer matrix and set $\hat p_n:=\hat p(A,S_n)$.

Suppose that 
\begin{itemize}
\item[(A1)] $\hat p_n\to 0$ and $|S_n|\hat p_n\to\infty$ as $n\to\infty$;
\item[(A2)] $(S_n)_{n \in \mathbb N}$ is $(A,r)$-supersaturated; 
\item[(A3)] there exists $B\ge1$ such that the pair $(A,S_n)$ is $B$-extendable for all sufficiently large $n\in\mathbb N$;
\item[(A4)] there exists $D>0$ such that for every $W\subset Y\subseteq[k]$ with $|W|=1$ and $w_0\in S_n$, we have $|\mathrm{Sol}_{S_n}^A(w_0,W,Y)|\le D\frac{|\mathrm{Sol}_{S_n}^A(Y)|}{|S_n|}$ for all sufficiently large $n\in\mathbb N$; 
\item[(A5)] $(S_n)_{n \in \mathbb N}$ is compatible with respect to $A$;
\item[(A6)] $(S_n)_{n \in \mathbb N}$ is weakly compatible with respect to $A$.
\end{itemize}
Then there exist constants $c,C>0$ such that
$$\lim _{n \rightarrow \infty} \mathbb P [ S_{n,p} \text{ is } (A,r)\text{-Rado}]=\begin{cases}
0 &\text{ if } p\leq {c}\hat p_n; \\
 1 &\text{ if } p\geq {C}\hat p_n.\end{cases}$$

$$\lim _{n \rightarrow \infty} \mathbb P [ S_{n,p} \text{ is } (A,r)\text{-Rado}]=\begin{cases}
0 &\text{ if } p\leq {c}\hat p_n; \\
 1 &\text{ if } p\geq {C}\hat p_n.\end{cases}$$

\label{def:rankfinite}
Let $S$ be a finite abelian group. Let $A$ be an $\ell\times k$ integer matrix and let $f_A:S^k\to S^\ell$ be the function defined by $f_A:x\mapsto Ax$. We define
\begin{align*}
\mathrm{rank}_S(A):=
\begin{cases}
\log_{|S|} |\mathrm{im}(f_A)| & \text{if } |S|>1;\\
0 & \text{if } |S|=1.
\end{cases}
\end{align*}

\begin{align*}
\mathrm{rank}_S(A):=
\begin{cases}
\log_{|S|} |\mathrm{im}(f_A)| & \text{if } |S|>1;\\
0 & \text{if } |S|=1.
\end{cases}
\end{align*}

\begin{align}\label{eq:rank1}
\begin{cases}
|\ker(f_A)|=\frac{|S|^k}{|\mathrm{im}(f_A)|}=|S|^{k-\mathrm{rank}_S(A)} & \text{if } b \in \mathrm{im}(f_A);\\
0 & \text{otherwise.}
\end{cases}
\end{align}

\label{lem:keycounting}
Let $A$ be an $\ell\times k$ integer matrix. Suppose that either
\begin{itemize}
\item[(i)] $S$ is a finite abelian group or 
\item[(ii)] $S=L^d$ for some finite subset $L$ of a field and $d\in\mathbb N$. 
\end{itemize}
Then for all  $W \subseteq Y \subseteq [k]$ and $w_0 \in S^{|W|}$ we have
\begin{align}\label{eq:key1}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le|S|^{|Y|-|W|-\mathrm{rank}_{S}(A_{\overline{W}})+\mathrm{rank}_{S}(A_{\overline{Y}})}.    
\end{align}

\begin{align}\label{eq:key1}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le|S|^{|Y|-|W|-\mathrm{rank}_{S}(A_{\overline{W}})+\mathrm{rank}_{S}(A_{\overline{Y}})}.    
\end{align}

\begin{equation}\label{eq:count1}
|\mathrm{Sol}_S^A(w_0,W,[k])|=|S|^{k-|W|-\mathrm{rank}_S({A_{\overline W}})}.
\end{equation}

\label{col:keycounting}
Let $A$ be an $\ell\times k$ integer matrix and let $0<\varepsilon \leq 1$. Suppose that either
\begin{itemize}
\item[(i)] $S$ is a finite abelian group or 
\item[(ii)] $S=L^d$ for some finite subset $L$ of a field and $d\in\mathbb N$.  
\end{itemize}
If $(A,S)$ is $\varepsilon$-rich, then for every non-empty $Z\subseteq[k]$ we have
\begin{align}\label{eq:key2}
\varepsilon|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}\le|\mathrm{Sol}_S^A(Z)|\le|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}.
\end{align}

\begin{align}\label{eq:key2}
\varepsilon|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}\le|\mathrm{Sol}_S^A(Z)|\le|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}.
\end{align}

Fix $Z\subseteq[k]$. Applying~\eqref{eq:key1} from Lemma~\ref{lem:keycounting} with $Y:=Z$ and $W:=\emptyset$ yields the upper bound
$$|\mathrm{Sol}_S^A(Z)|\le|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}.$$
Fix $z_0\in\mathrm{Sol}_S^A(Z)$. By applying~\eqref{eq:key1} with $Y:=[k]$ and $W:=Z$, we obtain that
\begin{equation}\label{eq:upperbound1}
|\mathrm{Sol}_S^A(z_0,Z,[k])|\le|S|^{k-|Z|-\mathrm{rank}_S(A_{\overline Z})}.
\end{equation}
The total number of solutions to $Ax=0$ in $S$ is 
$$|\mathrm{Sol}_S^A([k])|=\sum_{z_0\in\mathrm{Sol}_S^A(Z)}|\mathrm{Sol}_S^A(z_0,Z,[k])|\stackrel{\eqref{eq:upperbound1}}{\le}|\mathrm{Sol}_S^A(Z)|\cdot|S|^{k-|Z|-\mathrm{rank}_S(A_{\overline Z})}.$$
Combining the above with $|\mathrm{Sol}_S^A([k])|\ge\varepsilon|S|^{k-\mathrm{rank}_{S}(A)}$ yields
\begin{align*}
|\mathrm{Sol}_S^A(Z)|&\ge\varepsilon|S|^{k-\mathrm{rank}_S(A)}\cdot|S|^{-k+|Z|+\mathrm{rank}_S(A_{\overline Z})}=\varepsilon|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}.
\end{align*}

\begin{equation}\label{eq:upperbound1}
|\mathrm{Sol}_S^A(z_0,Z,[k])|\le|S|^{k-|Z|-\mathrm{rank}_S(A_{\overline Z})}.
\end{equation}

\begin{align*}
|\mathrm{Sol}_S^A(Z)|&\ge\varepsilon|S|^{k-\mathrm{rank}_S(A)}\cdot|S|^{-k+|Z|+\mathrm{rank}_S(A_{\overline Z})}=\varepsilon|S|^{|Z|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Z})}.
\end{align*}

\label{lem:simplifiedA3}
Let $A$ be an $\ell\times k$ integer matrix. Suppose that either
\begin{itemize}
\item[(i)] $S$ is a finite abelian group or 
\item[(ii)] $S=L^d$ for some finite subset $L$ of a field and $d\in\mathbb N$. 
\end{itemize}
If there exists $B>0$ such that $(A,S)$ is $(1/B)$-rich, then $(A,S)$ is $B$-extendable.

Let $W\subseteq Y\subseteq[k]$ and $w_0\in S^{|W|}$. It follows from Lemma~\ref{lem:keycounting} and Corollary~\ref{col:keycounting} that
\begin{align*}
\frac{B|\mathrm{Sol}_S^A(Y)|}{|\mathrm{Sol}_S^A(W)|}\stackrel{\eqref{eq:key2}}{\ge}\frac{|S|^{|Y|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Y})}}{|S|^{|W|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline W})}}=|S|^{|Y|-|W|-\mathrm{rank}_S(A_{\overline W})+\mathrm{rank}_S(A_{\overline Y})}\stackrel{\eqref{eq:key1}}{\ge}|\mathrm{Sol}_S^A(w_0,W,Y)|.
\end{align*}
Hence $(A,S)$ is $B$-extendable.

\begin{align*}
\frac{B|\mathrm{Sol}_S^A(Y)|}{|\mathrm{Sol}_S^A(W)|}\stackrel{\eqref{eq:key2}}{\ge}\frac{|S|^{|Y|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline Y})}}{|S|^{|W|-\mathrm{rank}_S(A)+\mathrm{rank}_S(A_{\overline W})}}=|S|^{|Y|-|W|-\mathrm{rank}_S(A_{\overline W})+\mathrm{rank}_S(A_{\overline Y})}\stackrel{\eqref{eq:key1}}{\ge}|\mathrm{Sol}_S^A(w_0,W,Y)|.
\end{align*}

\label{lem:spreadedges}
Let $A$ be an $\ell\times k$ integer matrix. Suppose that either
\begin{itemize}
\item[(i)] $S$ is a finite abelian group or 
\item[(ii)] $S=L^d$ for some finite subset $L$ of a field and $d\in\mathbb N$.
\end{itemize}
Furthermore, assume that $(A,S)$ is abundant and $\varepsilon$-rich for some $0<\varepsilon\leq 1$. Then, for every $W\subseteq Y\subseteq[k]$ with $|W|=1$ and $w_0 \in S$ we have $|\mathrm{Sol}_S^A(w_0,W,Y)|\le |\mathrm{Sol}_S^A(Y)|/(\varepsilon |S|)$.

By Lemma~\ref{lem:keycounting} we have 
\begin{align*}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le|S|^{|Y|-1-\mathrm{rank}_{S}(A_{\overline{W}})+\mathrm{rank}_{S}(A_{\overline{Y}})},
\end{align*}
while by Corollary~\ref{col:keycounting} we have
\begin{align*}
|\mathrm{Sol}_S^A(Y)|\ge\varepsilon|S|^{|Y|-\mathrm{rank}_{S}(A)
+\mathrm{rank}_{S}(A_{\overline{Y}})}.
\end{align*}
Combining the two inequalities above yields
\begin{align}\label{newlabel1}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le \frac{1}{\varepsilon} \cdot\frac{|\mathrm{Sol}_S^A(Y)|}{|S|}\cdot|S|^{\mathrm{rank}_{S}(A)
-\mathrm{rank}_{S}(A_{\overline{W}})}.
\end{align}
