 $\mathrm{rank}_S(A_{\overline W})=\mathrm{rank}_S(A)$ and so (\ref{newlabel1}) implies that $|\mathrm{Sol}_S^A(w_0,W,Y)|\le|\mathrm{Sol}_S^A(Y)|/(\varepsilon |S|)$.

\begin{align*}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le|S|^{|Y|-1-\mathrm{rank}_{S}(A_{\overline{W}})+\mathrm{rank}_{S}(A_{\overline{Y}})},
\end{align*}

\begin{align*}
|\mathrm{Sol}_S^A(Y)|\ge\varepsilon|S|^{|Y|-\mathrm{rank}_{S}(A)
+\mathrm{rank}_{S}(A_{\overline{Y}})}.
\end{align*}

\begin{align}\label{newlabel1}
|\mathrm{Sol}_S^A(w_0,W,Y)|\le \frac{1}{\varepsilon} \cdot\frac{|\mathrm{Sol}_S^A(Y)|}{|S|}\cdot|S|^{\mathrm{rank}_{S}(A)
-\mathrm{rank}_{S}(A_{\overline{W}})}.
\end{align}

