\label{thm:mainramsey}
Let  $r,k \geq 2$ be integers, and let $b>0$.
Let $(\mathcal{H}_n)_{n \in \mathbb{N}}$ be a sequence of $k$-uniform ordered hypergraphs and set $\hat p_n:=\hat p(\mathcal{H}_n)$ as given by~(\ref{eq:keyprobability}). Let (P1)--(P5) be the following properties. 
\begin{enumerate}
\item[(P1)] Probabilities: $\hat p_n \to 0$ and $\hat p_n v(\mathcal{H}_n) \to \infty$ as $n \to \infty$.
\item[(P2)] Supersaturation: $(\mathcal{H}_n)_{n \in \mathbb{N}}$ is $r$-supersaturated.
\item[(P3)] Bounded degree: 
for any $W \subseteq Y \subseteq [k]$, and any sufficiently large $n \in \mathbb N$  we have
$\Delta_W(\mathcal{H}_{n,Y}) \leq b \frac{e(\mathcal{H}_{n,Y})}{e(\mathcal{H}_{n,W})}$. 

\item[(P4)] Bounded $1$-degree: for any $W \subset Y \subseteq [k]$ with $|W|=1$ and any sufficiently large $n \in \mathbb N$, we have
$\Delta_W(\mathcal{H}_{n,Y}) \leq b \frac{e(\mathcal{H}_{n,Y})}{v(\mathcal{H}_{n})}$.
\item[(P5)] Bounded $2$-degree: there exists a sequence $(X_n)_{n\in\mathbb N}$ of subsets $X_n\subseteq[k]$ with $|X_n|\ge3$ for all $n\in\mathbb N$ such that
\begin{equation}\label{eq:P4a}
f_{n,X_n}=\Omega(\hat p_n)
\end{equation}
and 
\begin{equation}\label{eq:P4b}
\Delta_{W_n}(\mathcal{H}_{n,X_n}) \cdot \Delta_{W'_n}(\mathcal{H}_{n,X_n})\cdot e(\mathcal{H}_{n,X_n}) \cdot (\hat p_n)^{3|X_n|-2-|W'_n|} = o(1)
\end{equation} 
for any sequences $(W_n)_{n\in\mathbb N}$ and $(W'_n)_{n\in\mathbb N}$ with $W_n,W'_n\subset X_n$, $|W_n|=2$ and $|W'_n|\ge2$.
\end{enumerate}

